-- MySQL 5.7 fallback for CHECK constraints. Run once after 009_validate_integrity.sql
-- and 011_add_user_active_status.sql when the users.is_active column is not already present.
-- Enforces the row-level rules from 010 via BEFORE INSERT/UPDATE triggers.
-- Native CHECK constraints require MySQL 8.0.16+; cross-row rules are protected by unique indexes/foreign keys.
-- Legacy MySQL 5.7 schema uses utf8mb4_unicode_ci for UUID columns.
-- Create the equivalent unique keys and product/color relation before row triggers.
ALTER TABLE addresses ADD COLUMN default_user_id CHAR(36) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (CASE WHEN is_default=1 THEN user_id ELSE NULL END) VIRTUAL, ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE addresses ADD UNIQUE KEY uq_addresses_single_default (default_user_id), ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE order_items ADD UNIQUE KEY uq_order_items_variant (order_id,variant_id), ALGORITHM=INPLACE, LOCK=NONE;
CREATE TABLE product_colors (product_id CHAR(36) COLLATE utf8mb4_unicode_ci NOT NULL, color_id INT UNSIGNED NOT NULL, PRIMARY KEY (product_id,color_id), CONSTRAINT fk_product_colors_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE, CONSTRAINT fk_product_colors_color FOREIGN KEY (color_id) REFERENCES colors(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO product_colors (product_id,color_id) SELECT DISTINCT product_id,color_id FROM product_variants;
SET SESSION foreign_key_checks=0;
ALTER TABLE product_variants ADD CONSTRAINT fk_variants_product_color FOREIGN KEY (product_id,color_id) REFERENCES product_colors(product_id,color_id), ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE product_images ADD CONSTRAINT fk_images_product_color FOREIGN KEY (product_id,color_id) REFERENCES product_colors(product_id,color_id), ALGORITHM=INPLACE, LOCK=NONE;
SET SESSION foreign_key_checks=1;
DELIMITER $$
CREATE TRIGGER trg_ck_users_bi BEFORE INSERT ON users FOR EACH ROW BEGIN IF (BINARY NEW.role NOT IN (BINARY 'customer', BINARY 'admin') OR BINARY NEW.email <> BINARY LOWER(NEW.email) OR NEW.email NOT REGEXP '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' OR (NEW.phone IS NOT NULL AND NEW.phone NOT REGEXP '^0[0-9]{9}$') OR CHAR_LENGTH(TRIM(NEW.full_name))=0 OR CHAR_LENGTH(TRIM(NEW.password_hash))=0 OR NEW.is_active NOT IN (0,1)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='users integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_users_bu BEFORE UPDATE ON users FOR EACH ROW BEGIN IF (BINARY NEW.role NOT IN (BINARY 'customer', BINARY 'admin') OR BINARY NEW.email <> BINARY LOWER(NEW.email) OR NEW.email NOT REGEXP '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' OR (NEW.phone IS NOT NULL AND NEW.phone NOT REGEXP '^0[0-9]{9}$') OR CHAR_LENGTH(TRIM(NEW.full_name))=0 OR CHAR_LENGTH(TRIM(NEW.password_hash))=0 OR NEW.is_active NOT IN (0,1)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='users integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_addresses_bi BEFORE INSERT ON addresses FOR EACH ROW BEGIN IF (NEW.is_default NOT IN (0,1) OR CHAR_LENGTH(TRIM(NEW.recipient_name))=0 OR CHAR_LENGTH(TRIM(NEW.province))=0 OR CHAR_LENGTH(TRIM(NEW.ward))=0 OR CHAR_LENGTH(TRIM(NEW.street))=0 OR NEW.phone NOT REGEXP '^0[0-9]{9}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='address integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_addresses_bu BEFORE UPDATE ON addresses FOR EACH ROW BEGIN IF (NEW.is_default NOT IN (0,1) OR CHAR_LENGTH(TRIM(NEW.recipient_name))=0 OR CHAR_LENGTH(TRIM(NEW.province))=0 OR CHAR_LENGTH(TRIM(NEW.ward))=0 OR CHAR_LENGTH(TRIM(NEW.street))=0 OR NEW.phone NOT REGEXP '^0[0-9]{9}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='address integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_categories_bi BEFORE INSERT ON categories FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.name))=0 OR CHAR_LENGTH(TRIM(NEW.slug))=0 OR BINARY NEW.slug <> BINARY LOWER(NEW.slug) OR NEW.sort_order < 0 OR NEW.parent_id=NEW.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='category integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_categories_bu BEFORE UPDATE ON categories FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.name))=0 OR CHAR_LENGTH(TRIM(NEW.slug))=0 OR BINARY NEW.slug <> BINARY LOWER(NEW.slug) OR NEW.sort_order < 0 OR NEW.parent_id=NEW.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='category integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_colors_bi BEFORE INSERT ON colors FOR EACH ROW BEGIN IF (NEW.hex_code NOT REGEXP '^#[0-9A-Fa-f]{6}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='color hex code is invalid'; END IF; END$
CREATE TRIGGER trg_ck_colors_bu BEFORE UPDATE ON colors FOR EACH ROW BEGIN IF (NEW.hex_code NOT REGEXP '^#[0-9A-Fa-f]{6}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='color hex code is invalid'; END IF; END$
CREATE TRIGGER trg_ck_sizes_bi BEFORE INSERT ON sizes FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.name))=0 OR NEW.sort_order < 0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='size integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_sizes_bu BEFORE UPDATE ON sizes FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.name))=0 OR NEW.sort_order < 0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='size integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_products_bi BEFORE INSERT ON products FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.name))=0 OR (NEW.description IS NOT NULL AND CHAR_LENGTH(NEW.description)>5000) OR BINARY NEW.product_type NOT IN (BINARY 'shirt',BINARY 'pants',BINARY 'dress',BINARY 'jacket',BINARY 'skirt',BINARY 'hat',BINARY 'bag',BINARY 'wallet',BINARY 'belt',BINARY 'socks',BINARY 'sandals',BINARY 'shoes',BINARY 'gloves',BINARY 'other') OR BINARY NEW.gender NOT IN (BINARY 'women',BINARY 'men',BINARY 'unisex') OR BINARY NEW.status NOT IN (BINARY 'draft',BINARY 'active',BINARY 'archived') OR BINARY NEW.slug <> BINARY LOWER(NEW.slug) OR NEW.base_price NOT BETWEEN 1 AND 1000000000 OR (NEW.sale_price IS NOT NULL AND (NEW.sale_price < 1 OR NEW.sale_price >= NEW.base_price)) OR NEW.is_featured NOT IN (0,1) OR NEW.is_new NOT IN (0,1)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='product integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_products_bu BEFORE UPDATE ON products FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.name))=0 OR (NEW.description IS NOT NULL AND CHAR_LENGTH(NEW.description)>5000) OR BINARY NEW.product_type NOT IN (BINARY 'shirt',BINARY 'pants',BINARY 'dress',BINARY 'jacket',BINARY 'skirt',BINARY 'hat',BINARY 'bag',BINARY 'wallet',BINARY 'belt',BINARY 'socks',BINARY 'sandals',BINARY 'shoes',BINARY 'gloves',BINARY 'other') OR BINARY NEW.gender NOT IN (BINARY 'women',BINARY 'men',BINARY 'unisex') OR BINARY NEW.status NOT IN (BINARY 'draft',BINARY 'active',BINARY 'archived') OR BINARY NEW.slug <> BINARY LOWER(NEW.slug) OR NEW.base_price NOT BETWEEN 1 AND 1000000000 OR (NEW.sale_price IS NOT NULL AND (NEW.sale_price < 1 OR NEW.sale_price >= NEW.base_price)) OR NEW.is_featured NOT IN (0,1) OR NEW.is_new NOT IN (0,1)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='product integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_product_images_bi BEFORE INSERT ON product_images FOR EACH ROW BEGIN IF (NEW.url NOT REGEXP '^(https?://|/)' OR NEW.sort_order < 0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='product image integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_product_images_bu BEFORE UPDATE ON product_images FOR EACH ROW BEGIN IF (NEW.url NOT REGEXP '^(https?://|/)' OR NEW.sort_order < 0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='product image integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_product_variants_bi BEFORE INSERT ON product_variants FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.sku))=0 OR (NEW.price_override IS NOT NULL AND NEW.price_override NOT BETWEEN 1 AND 1000000000) OR NEW.stock_quantity > 1000000) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='product variant integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_product_variants_bu BEFORE UPDATE ON product_variants FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.sku))=0 OR (NEW.price_override IS NOT NULL AND NEW.price_override NOT BETWEEN 1 AND 1000000000) OR NEW.stock_quantity > 1000000) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='product variant integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_carts_bi BEFORE INSERT ON carts FOR EACH ROW BEGIN IF (((NEW.user_id IS NULL AND NEW.session_token IS NULL) OR (NEW.user_id IS NOT NULL AND NEW.session_token IS NOT NULL)) OR (NEW.session_token IS NOT NULL AND CHAR_LENGTH(TRIM(NEW.session_token))=0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='cart must have exactly one non-empty owner'; END IF; END$
CREATE TRIGGER trg_ck_carts_bu BEFORE UPDATE ON carts FOR EACH ROW BEGIN IF (((NEW.user_id IS NULL AND NEW.session_token IS NULL) OR (NEW.user_id IS NOT NULL AND NEW.session_token IS NOT NULL)) OR (NEW.session_token IS NOT NULL AND CHAR_LENGTH(TRIM(NEW.session_token))=0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='cart must have exactly one non-empty owner'; END IF; END$
CREATE TRIGGER trg_ck_cart_items_bi BEFORE INSERT ON cart_items FOR EACH ROW BEGIN IF (NEW.quantity NOT BETWEEN 1 AND 20) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='cart quantity must be between 1 and 20'; END IF; END$
CREATE TRIGGER trg_ck_cart_items_bu BEFORE UPDATE ON cart_items FOR EACH ROW BEGIN IF (NEW.quantity NOT BETWEEN 1 AND 20) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='cart quantity must be between 1 and 20'; END IF; END$
CREATE TRIGGER trg_ck_coupons_bi BEFORE INSERT ON coupons FOR EACH ROW BEGIN IF (BINARY NEW.code <> BINARY UPPER(NEW.code) OR BINARY NEW.code NOT REGEXP '^[A-Z0-9_-]{3,30}$' OR BINARY NEW.discount_type NOT IN (BINARY 'percent',BINARY 'fixed') OR NEW.value NOT BETWEEN 1 AND 1000000000 OR (NEW.discount_type='percent' AND NEW.value>100) OR NEW.min_order_amount>1000000000 OR (NEW.max_discount IS NOT NULL AND NEW.max_discount NOT BETWEEN 1 AND 1000000000) OR (NEW.usage_limit IS NOT NULL AND (NEW.usage_limit=0 OR NEW.used_count>NEW.usage_limit)) OR NEW.is_active NOT IN (0,1) OR (NEW.starts_at IS NOT NULL AND NEW.ends_at IS NOT NULL AND NEW.ends_at<NEW.starts_at)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='coupon integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_coupons_bu BEFORE UPDATE ON coupons FOR EACH ROW BEGIN IF (BINARY NEW.code <> BINARY UPPER(NEW.code) OR BINARY NEW.code NOT REGEXP '^[A-Z0-9_-]{3,30}$' OR BINARY NEW.discount_type NOT IN (BINARY 'percent',BINARY 'fixed') OR NEW.value NOT BETWEEN 1 AND 1000000000 OR (NEW.discount_type='percent' AND NEW.value>100) OR NEW.min_order_amount>1000000000 OR (NEW.max_discount IS NOT NULL AND NEW.max_discount NOT BETWEEN 1 AND 1000000000) OR (NEW.usage_limit IS NOT NULL AND (NEW.usage_limit=0 OR NEW.used_count>NEW.usage_limit)) OR NEW.is_active NOT IN (0,1) OR (NEW.starts_at IS NOT NULL AND NEW.ends_at IS NOT NULL AND NEW.ends_at<NEW.starts_at)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='coupon integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_orders_bi BEFORE INSERT ON orders FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.code))=0 OR BINARY NEW.status NOT IN (BINARY 'pending',BINARY 'confirmed',BINARY 'shipping',BINARY 'completed',BINARY 'cancelled') OR BINARY NEW.payment_method NOT IN (BINARY 'cod',BINARY 'bank_transfer',BINARY 'ewallet',BINARY 'sepay') OR BINARY NEW.payment_status NOT IN (BINARY 'unpaid',BINARY 'paid',BINARY 'refunded') OR NEW.subtotal<1 OR NEW.discount_amount>NEW.subtotal OR NEW.total+NEW.discount_amount<>NEW.subtotal+NEW.shipping_fee OR CHAR_LENGTH(TRIM(NEW.recipient_name))=0 OR NEW.phone NOT REGEXP '^0[0-9]{9}$' OR BINARY NEW.email<>BINARY LOWER(NEW.email) OR NEW.email NOT REGEXP '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' OR CHAR_LENGTH(TRIM(NEW.shipping_address))=0 OR CHAR_LENGTH(NEW.shipping_address)>500 OR (NEW.note IS NOT NULL AND CHAR_LENGTH(NEW.note)>1000)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='order integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_orders_bu BEFORE UPDATE ON orders FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.code))=0 OR BINARY NEW.status NOT IN (BINARY 'pending',BINARY 'confirmed',BINARY 'shipping',BINARY 'completed',BINARY 'cancelled') OR BINARY NEW.payment_method NOT IN (BINARY 'cod',BINARY 'bank_transfer',BINARY 'ewallet',BINARY 'sepay') OR BINARY NEW.payment_status NOT IN (BINARY 'unpaid',BINARY 'paid',BINARY 'refunded') OR NEW.subtotal<1 OR NEW.discount_amount>NEW.subtotal OR NEW.total+NEW.discount_amount<>NEW.subtotal+NEW.shipping_fee OR CHAR_LENGTH(TRIM(NEW.recipient_name))=0 OR NEW.phone NOT REGEXP '^0[0-9]{9}$' OR BINARY NEW.email<>BINARY LOWER(NEW.email) OR NEW.email NOT REGEXP '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' OR CHAR_LENGTH(TRIM(NEW.shipping_address))=0 OR CHAR_LENGTH(NEW.shipping_address)>500 OR (NEW.note IS NOT NULL AND CHAR_LENGTH(NEW.note)>1000)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='order integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_order_items_bi BEFORE INSERT ON order_items FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.product_name))=0 OR CHAR_LENGTH(TRIM(NEW.color_name))=0 OR CHAR_LENGTH(TRIM(NEW.size_name))=0 OR NEW.unit_price NOT BETWEEN 1 AND 1000000000 OR NEW.quantity NOT BETWEEN 1 AND 20) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='order item integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_order_items_bu BEFORE UPDATE ON order_items FOR EACH ROW BEGIN IF (CHAR_LENGTH(TRIM(NEW.product_name))=0 OR CHAR_LENGTH(TRIM(NEW.color_name))=0 OR CHAR_LENGTH(TRIM(NEW.size_name))=0 OR NEW.unit_price NOT BETWEEN 1 AND 1000000000 OR NEW.quantity NOT BETWEEN 1 AND 20) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='order item integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_reviews_bi BEFORE INSERT ON reviews FOR EACH ROW BEGIN IF (NEW.rating NOT BETWEEN 1 AND 5 OR (NEW.comment IS NOT NULL AND CHAR_LENGTH(NEW.comment)>1000)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='review integrity rule violated'; END IF; END$
CREATE TRIGGER trg_ck_reviews_bu BEFORE UPDATE ON reviews FOR EACH ROW BEGIN IF (NEW.rating NOT BETWEEN 1 AND 5 OR (NEW.comment IS NOT NULL AND CHAR_LENGTH(NEW.comment)>1000)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='review integrity rule violated'; END IF; END$
CREATE TRIGGER trg_orders_completed_unpaid_bi BEFORE INSERT ON orders FOR EACH ROW BEGIN IF NEW.status='completed' AND NEW.payment_status='unpaid' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='cannot complete an unpaid order'; END IF; END$
CREATE TRIGGER trg_orders_completed_unpaid_bu BEFORE UPDATE ON orders FOR EACH ROW BEGIN IF NEW.status='completed' AND NEW.payment_status='unpaid' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='cannot complete an unpaid order'; END IF; END$
DELIMITER ;
